  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_light;
#if TWO_COLORED
  in vec4 v_dark;
#endif
in vec2 uv0;
layout(std140) uniform RainbowParams {
  vec4 rainbowCenter;
  vec4 rainbowNoiseScale;
  float rainbowFade;
  float rainbowBrightness;
  float rainbowSaturation;
  float rainbowContrast;
  float rainbowSpeed;
  float rainbowDensity;
  float rainbowNoiseFactor;
};
#if OUTBASE_ON
  layout(std140) uniform OutlineParams {
    vec4 outlineColor;
    float outlineWidth;
    float outlineAlpha;
    float outlineGlow;
  };
#endif
#if OUTTEX_ON
  layout(std140) uniform OutlineTexParams {
    float outlineTexXSpeed;
    float outlineTexYSpeed;
  };
  uniform sampler2D outlineTexture;
#endif
#if OUTDIST_ON
  layout(std140) uniform OutlineDistParams {
    float outlineDistortAmount;
    float outlineDistortXSpeed;
    float outlineDistortYSpeed;
  };
  uniform sampler2D outlineDistortTexture;
#endif
uniform sampler2D cc_spriteTexture;
uniform sampler2D noiseTexture;
vec3 HSVToRGB( vec3 c ) {
  vec4 K = vec4( 1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0 );
  vec3 p1 = abs( fract( c.xxx + K.xyz ) * 6.0 - K.www );
  return c.z * mix( K.xxx, clamp( p1 - K.xxx, 0.0, 1.0 ), c.y );
}
vec3 RGBToHSV(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p2 = mix( vec4( c.bg, K.wz ), vec4( c.gb, K.xy ), step( c.b, c.g ) );
  vec4 q = mix( vec4( p2.xyw, c.r ), vec4( c.r, p2.yzx ), step( p2.x, c.r ) );
  float d = q.x - min( q.w, q.y );
  float e = 1.0e-10;
  return vec3( abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
